func f(x int) int {
	if x > 0 {
		return x + f(x-1)
	}
	return 0 // f(0) = 0
}

func mergeTwoLists(l1 *ListNode, l2 *ListNode) *ListNode {
	if l1 == nil {
		return l2 // 终止条件，直到两个链表都空
	}
	if l2 == nil {
		return l1
	}
	if l1.Val <= l2.Val { // 递归调用
		l1.Next = mergeTwoLists(l1.Next, l2)
		return l1
	}
	l2.Next = mergeTwoLists(l1, l2.Next)
	return l2
}

